package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;

/**
 * Normalizes a create request's address to its canonical form — trimmed, whitespace
 * collapsed, upper-cased and with common street-type abbreviations expanded (see
 * {@link Addresses#normalize(String)}) — storing the result back on the body so later
 * steps compare, persist and return the canonical value. Runs after
 * {@link ValidateOwnerFields} has confirmed the address is not blank once normalized and
 * published the body; mutates that same instance in place.
 */
public class NormalizeOwnerAddress {

    public void service(@Val OwnerFieldsDto request) {
        request.setAddress(Addresses.normalize(request.getAddress()));
    }
}

===== EnsureUniqueTelephone.java =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Rejects a create request whose E.164 telephone is already used by an existing owner. Runs
 * after {@link NormalizeOwnerTelephone} has canonicalized the body's telephone, comparing it
 * against every stored owner's E.164 number so numbers that differ only in separators or an
 * assumed country code are still treated as duplicates.
 */
public class EnsureUniqueTelephone {

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws DuplicateTelephoneException {
        String telephone = request.getTelephone();
        for (Owner owner : ownerRepository.findAll()) {
            if (Telephones.toE164(owner.getTelephone()).filter(telephone::equals).isPresent()) {
                throw new DuplicateTelephoneException(telephone);
            }
        }
    }
}

===== EnsureUniqueHousehold.java =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Rejects a create request that would place a new owner in a household already occupied by
 * an existing owner — one sharing the same last name and address, compared in their
 * canonical forms (see {@link Households#matches(org.springframework.samples.petclinic.model.Owner, String, String)}).
 * A request may opt in to a shared household by setting {@code sharesHousehold} true, in
 * which case the check is skipped.
 */
public class EnsureUniqueHousehold {

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws DuplicateHouseholdException {
        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
            return;
        }
        for (Owner owner : ownerRepository.findAll()) {
            if (Households.matches(owner, request.getLastName(), request.getAddress())) {
                throw new DuplicateHouseholdException(request.getLastName(), request.getAddress());
            }
        }
    }
}

