===== Telephones.java =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Optional;

/**
 * Shared telephone handling: converts a raw number to its canonical E.164 form so numbers
 * written with different separators (or an explicit country code) compare equal. Used both
 * to normalize a create request before it is persisted and to compare it against existing
 * owners' stored numbers.
 */
final class Telephones {

    /** Country code assumed when the input carries no explicit '+' prefix (Australia). */
    private static final String DEFAULT_COUNTRY_CODE = "61";

    private Telephones() {
    }

    /**
     * Converts {@code telephone} to E.164 (a leading '+' followed by 8 to 15 digits).
     *
     * <p>Spaces, dashes and brackets are stripped. When the number keeps a leading '+' its
     * country code is preserved; otherwise {@code +61} is assumed and a single leading '0'
     * is dropped from the national digits. Returns empty when the result cannot form valid
     * E.164 (non-digits remain, or the digit count is out of range).
     */
    static Optional<String> toE164(String telephone) {
        if (telephone == null) {
            return Optional.empty();
        }
        String cleaned = telephone.replaceAll("[\\s()\\-]", "");
        String digits;
        if (cleaned.startsWith("+")) {
            digits = cleaned.substring(1);
        }
        else {
            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
            digits = DEFAULT_COUNTRY_CODE + national;
        }
        if (!digits.matches("[0-9]{8,15}")) {
            return Optional.empty();
        }
        return Optional.of("+" + digits);
    }
}

===== Emails.java =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;
import java.util.regex.Pattern;

/**
 * Shared email handling: a syntactic validity check and canonicalization to lower case, so
 * equivalent addresses written with different letter cases are stored and returned in one
 * uniform form. Used to normalize an owner request's optional email before it is persisted.
 */
final class Emails {

    private static final Pattern VALID = Pattern.compile(
            "^[A-Za-z0-9!#$%&'*+/=?^_`{|}~-]+(?:\\.[A-Za-z0-9!#$%&'*+/=?^_`{|}~-]+)*"
                    + "@[A-Za-z0-9](?:[A-Za-z0-9-]*[A-Za-z0-9])?"
                    + "(?:\\.[A-Za-z0-9](?:[A-Za-z0-9-]*[A-Za-z0-9])?)+$");

    private Emails() {
    }

    /** Whether {@code email} is a syntactically valid address. */
    static boolean isValid(String email) {
        return email != null && VALID.matcher(email).matches();
    }

    /** Returns {@code email} lower-cased: its canonical stored form. */
    static String normalize(String email) {
        return email.toLowerCase(Locale.ROOT);
    }
}

===== Addresses.java =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;
import java.util.Map;

/**
 * Shared address handling: canonicalizes a free-text street address so equivalent
 * addresses written with different casing, spacing or common abbreviations are stored
 * and compared uniformly. Used both to normalize an owner request before it is persisted
 * and to compare addresses when detecting shared households (see {@link Households}).
 */
final class Addresses {

    /** Common street-type abbreviations expanded to their full word (whole words only). */
    private static final Map<String, String> ABBREVIATIONS = Map.of(
            "ST", "STREET",
            "RD", "ROAD",
            "AVE", "AVENUE");

    private Addresses() {
    }

    /**
     * Returns the canonical form of {@code address}: trimmed, with every run of
     * whitespace collapsed to a single space, upper-cased, and common street-type
     * abbreviations ({@code ST}, {@code RD}, {@code AVE}) expanded to their full words.
     * Returns {@code null} when {@code address} is {@code null}.
     */
    static String normalize(String address) {
        if (address == null) {
            return null;
        }
        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
        if (collapsed.isEmpty()) {
            return collapsed;
        }
        String[] words = collapsed.split(" ");
        StringBuilder result = new StringBuilder(collapsed.length());
        for (int i = 0; i < words.length; i++) {
            if (i > 0) {
                result.append(' ');
            }
            result.append(ABBREVIATIONS.getOrDefault(words[i], words[i]));
        }
        return result.toString();
    }
}

===== Cities.java =====
package org.springframework.samples.petclinic.rest.function.owner;

import org.springframework.samples.petclinic.model.Owner;

/**
 * City matching: two owners are in the same city when their city names are equal, compared
 * case-insensitively (and ignoring surrounding/internal whitespace). Used to count how many
 * existing owners already live in a new owner's city.
 */
final class Cities {

    private Cities() {
    }

    /**
     * Whether {@code owner} lives in the given city, comparing both in their canonical
     * (trimmed, whitespace-collapsed, lower-cased) forms.
     */
    static boolean matches(Owner owner, String city) {
        return normalize(city).equals(normalize(owner.getCity()));
    }

    private static String normalize(String city) {
        if (city == null) {
            return "";
        }
        return city.trim().replaceAll("\\s+", " ").toLowerCase();
    }
}

===== Households.java =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Locale;

import org.springframework.samples.petclinic.model.Owner;

/**
 * Shared household matching: canonicalizes the free-text fields that identify a household
 * (last name and address) so values that differ only in letter case, in the amount of
 * surrounding/internal whitespace, or (for the address) in common street-type
 * abbreviations compare equal. Used to detect when a new owner shares a household with an
 * existing one, and to derive the stable identifier that owners in the same household share.
 */
final class Households {

    private Households() {
    }

    /**
     * Canonicalizes a last name for case-insensitive, whitespace-insensitive comparison:
     * trims the ends, collapses every run of whitespace to a single space and lower-cases
     * the result. Returns an empty string when {@code lastName} is {@code null}.
     */
    private static String normalizeName(String lastName) {
        if (lastName == null) {
            return "";
        }
        return lastName.trim().replaceAll("\\s+", " ").toLowerCase();
    }

    /**
     * Canonicalizes an address using the same normalization applied when an owner is created
     * (see {@link Addresses#normalize(String)}), so household comparisons see the stored,
     * abbreviation-expanded form. Returns an empty string when {@code address} is
     * {@code null}.
     */
    private static String normalizeAddress(String address) {
        String normalized = Addresses.normalize(address);
        return normalized == null ? "" : normalized;
    }

    /**
     * Whether {@code owner} belongs to the household identified by {@code lastName} and
     * {@code address}, comparing the last name and the address in their canonical forms.
     */
    static boolean matches(Owner owner, String lastName, String address) {
        return normalizeName(lastName).equals(normalizeName(owner.getLastName()))
                && normalizeAddress(address).equals(normalizeAddress(owner.getAddress()));
    }

    /**
     * The stable identifier shared by every owner in the household identified by
     * {@code lastName} and {@code address}. Derived purely from the canonical household key,
     * so the same household always yields the same id without any coordination.
     */
    static String id(String lastName, String address) {
        String key = normalizeName(lastName) + "\n" + normalizeAddress(address);
        return "H-" + sha256Hex(key).substring(0, 12).toUpperCase(Locale.ROOT);
    }

    private static String sha256Hex(String value) {
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256")
                    .digest(value.getBytes(StandardCharsets.UTF_8));
            StringBuilder hex = new StringBuilder(digest.length * 2);
            for (byte b : digest) {
                hex.append(String.format("%02x", b));
            }
            return hex.toString();
        }
        catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException("SHA-256 not available", e);
        }
    }
}

===== CustomerCode.java =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;

/**
 * Formats an owner's customer code as {@code <CITY3>-<LAST3>-<NNNN>}, where {@code CITY3}
 * is the upper-cased first three letters of the city, {@code LAST3} the upper-cased first
 * three letters of the last name and {@code NNNN} a 4-digit zero-padded sequence number
 * (e.g. {@code LON-SMI-0007}).
 */
final class CustomerCode {

    private CustomerCode() {
    }

    static String format(String city, String lastName, int sequence) {
        return String.format("%s-%s-%04d", prefix(city), prefix(lastName), sequence);
    }

    private static String prefix(String value) {
        return value.substring(0, Math.min(3, value.length())).toUpperCase(Locale.ROOT);
    }
}

===== Namesakes.java =====
package org.springframework.samples.petclinic.rest.function.owner;

import org.springframework.samples.petclinic.model.Owner;

/**
 * Namesake matching: an owner is a namesake of another when they share the same first and
 * last name, compared case-insensitively (and ignoring surrounding/internal whitespace).
 * Used to count how many existing owners already carry a new owner's name.
 */
final class Namesakes {

    private Namesakes() {
    }

    /**
     * Whether {@code owner} shares the given first and last name, comparing both in their
     * canonical (trimmed, whitespace-collapsed, lower-cased) forms.
     */
    static boolean matches(Owner owner, String firstName, String lastName) {
        return normalize(firstName).equals(normalize(owner.getFirstName()))
                && normalize(lastName).equals(normalize(owner.getLastName()));
    }

    private static String normalize(String name) {
        if (name == null) {
            return "";
        }
        return name.trim().replaceAll("\\s+", " ").toLowerCase();
    }
}

